<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>سفارش جدید</title><style>body{font-family:Tahoma;background:#07111f;color:#e9f3fb;padding:30px}.box{max-width:850px;background:#0a1b2b;padding:24px;border-radius:14px}input,select,textarea{padding:10px;margin:6px;background:#10283c;color:#fff;border:1px solid #29465e;border-radius:8px}button{padding:10px 18px;background:#1c806e;color:#fff;border:0;border-radius:8px}.item{margin:10px 0}</style></head><body><div class="box"><h1>ثبت سفارش مشتری</h1><form method="post" action="{{ route('sales.orders.store') }}" onsubmit="return submitOrder(event)">@csrf<input type="hidden" name="fiscal_year_id" value="{{ $fiscalYear->id }}"><label>مشتری</label><select name="customer_id" required>@foreach($customers as $c)<option value="{{ $c->id }}">{{ $c->code }} - {{ $c->name }}</option>@endforeach</select><label>شماره سفارش</label><input name="number" required><label>تاریخ ثبت</label><input name="ordered_at" type="date" value="{{ now()->toDateString() }}" required><label>موعد درخواستی تحویل</label><input name="requested_delivery_at" type="date" required><div id="items"><div class="item"><select name="items[0][goods_id]" required>@foreach($goods as $g)<option value="{{ $g->id }}">{{ $g->code }} - {{ $g->name }}</option>@endforeach</select><input name="items[0][quantity]" type="number" step="0.0001" min="0.0001" placeholder="مقدار" required></div></div><button type="button" onclick="addItem()">+ قلم</button><textarea name="notes" placeholder="توضیحات"></textarea><button type="submit">ثبت سفارش و بررسی موجودی</button></form></div><script>let i=1;function addItem(){const s=document.querySelector('#items .item').cloneNode(true);s.querySelectorAll('[name]').forEach(e=>e.name=e.name.replace(/items\[0\]/,'items['+i+']'));s.querySelector('input[type=number]').value='';document.getElementById('items').appendChild(s);i++;}async function submitOrder(e){e.preventDefault();const f=e.target,r=await fetch(f.action,{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':f.querySelector('[name=_token]').value},body:new FormData(f)});const j=await r.json();if(!r.ok){alert(j.message||'خطا');return false}location.href='/sales/orders/'+j.data.id;}</script></body></html>